 user:[{name:"user_type",label:"User type",options:["Personal Executive (PE)","City Admin","Operations Admin","Finance Admin","Manager","Admin"],required:true},{name:"name",label:"Full name",required:true},{name:"email",label:"Email",type:"email"},{name:"phone",label:"Phone",type:"tel"},{name:"city",label:"City",source:"cities"},{name:"password",label:"Temporary password",type:"password"}],
