 plans:[{name:"code",label:"Plan code",required:true},{name:"name",label:"Plan name",required:true},{name:"market",label:"Market",options:["India","NRI","Corporate"],required:true},{name:"plan_type",label:"Plan type",options:["Individual","Family","Corporate","Other"]},{name:"eligibility",label:"Eligibility",type:"textarea",wide:true},{name:"description",label:"Description",type:"textarea",wide:true},{name:"entitlements",label:"Membership access & entitlements",type:"textarea",wide:true},{name:"included_services",label:"Services included",type:"textarea",wide:true},{name:"service_limits",label:"Service limits or credits",type:"textarea",wide:true},{name:"duration_years",label:"Duration (years)",type:"number",required:true},{name:"currency",label:"Currency",options:["INR","USD"],required:true},{name:"price_amount",label:"Current price",type:"number",required:true},{name:"standard_price",label:"Standard price from 2 Apr 2027",type:"number"},{name:"intro_price_until",label:"Intro price through",type:"date"},{name:"hours_per_year",label:"PE hours / benefit year",type:"number"},{name:"consultations_per_year",label:"Consultations / year",type:"number"},{name:"documentation_credit",label:"Documentation credit",type:"number"},{name:"status",label:"Visibility",options:["Active","Inactive","Draft"]},{name:"effective_from",label:"Membership begins",type:"date"},{name:"version",label:"Version"}],
