 requests:[{name:"member",label:"Member",source:"members",required:true},{name:"service",label:"Service",source:"services",required:true},{name:"beneficiary",label:"Beneficiary"},{name:"city",label:"Service city",source:"cities",required:true},{name:"location",label:"Service location"},{name:"scheduled_at",label:"Appointment time (India time)",type:"datetime-local"},{name:"duration_hours",label:"Expected PE hours",type:"number"},{name:"priority",label:"Priority",options:["Normal","Urgent","Emergency"]},{name:"quote_inr",label:"Quote (INR)",type:"number"},{name:"status",label:"Status",options:["New","Pending Approval","Assigned","Confirmed","In Progress","Completed","Cancelled"]},{name:"notes",label:"Instructions / notes",type:"textarea",wide:true}],
 pes:[{name:"name",label:"PE name",required:true},{name:"email",label:"Email",type:"email"},{name:"phone",label:"Phone",type:"tel"},{name:"city",label:"Service city",source:"cities",required:true},{name:"skills",label:"Skills (comma separated)"},{name:"shift_start",label:"Shift start",type:"time"},{name:"shift_end",label:"Shift end",type:"time"},{name:"status",label:"Roster status",options:["Active","Inactive","On leave"]}],
 payments:[{name:"member",label:"Member",source:"members",required:true},{name:"reference",label:"Reference / request"},{name:"kind",label:"Payment type",options:["Membership","Service","Adjustment"]},{name:"amount_inr",label:"Amount (INR)",type:"number",required:true},{name:"status",label:"Payment status",options:["Pending"]},{name:"gateway_reference",label:"Provider reference (verified events only)"},{name:"invoice_number",label:"Invoice number"},{name:"paid_at",label:"Paid at",type:"datetime-local"}],
 invoices:[{name:"invoice_number",label:"Invoice number",required:true},{name:"member",label:"Bill to",source:"members",required:true},{name:"amount_inr",label:"Amount (INR)",type:"number",required:true},{name:"due_date",label:"Due date",type:"date"},{name:"status",label:"Invoice status",options:["Unpaid","Overdue","Void"]},{name:"payment_reference",label:"Payment reference"}],
